// UI translation. The interface is written in Portuguese; when the language
// is English, every string the UI renders through h() (text, title,
// placeholder), toasts and dialogs included, is looked up here. Exact
// strings first, then patterns for sentences built with numbers or names.

let lang = 'pt';
export function setLang(l) {
  lang = l === 'en' ? 'en' : 'pt';
  document.documentElement.lang = lang === 'en' ? 'en' : 'pt-BR';
}
export function getLang() {
  return lang;
}
// Locale for dates and numbers: the UI language, not a fixed pt-BR.
export function locale() {
  return lang === 'en' ? 'en-US' : 'pt-BR';
}

